{% set _has_db = frappe is defined and frappe.db is defined %}
{% set _copy_no_raw = doc.get("copy_number") or (frappe.db.get_value("URY Bill Reprint Log", {"invoice": doc.get("name")}, "copy_number", order_by="copy_number desc") if (_has_db and doc.get("name")) else none) or 1 %}
{% set _copy_no_int = _copy_no_raw | int %}
{% set _copy_no = _copy_no_int if _copy_no_int > 0 else 1 %}
{% set _co_name = doc.get("company") if (doc.get("company") is string and doc.get("company") | trim) else none %}
{% set _rest_name = doc.get("restaurant") if (doc.get("restaurant") is string and doc.get("restaurant") | trim) else none %}
{% set _branch_name = doc.get("branch") if (doc.get("branch") is string and doc.get("branch") | trim) else none %}
{% set _co_raw = frappe.db.get_value("Company", _co_name, ["company_name", "tax_id", "phone_no", "company_logo"], as_dict=True) if (_has_db and _co_name) else none %}
{% set co = _co_raw if (_co_raw is mapping) else {} %}
{% set _rest_raw = frappe.db.get_value("URY Restaurant", _rest_name, ["name", "address", "tax_id", "image"], as_dict=True) if (_has_db and _rest_name) else none %}
{% set rest = _rest_raw if (_rest_raw is mapping) else {} %}
{% set _addr_name = (doc.get("company_address") if (doc.get("company_address") is string and doc.get("company_address") | trim) else none) or (rest.get("address") if (rest.get("address") is string and rest.get("address") | trim) else none) or (frappe.db.get_value("POS Profile", doc.get("pos_profile"), "company_address") if (_has_db and doc.get("pos_profile") is string and doc.get("pos_profile") | trim) else none) or (frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": _co_name, "parenttype": "Address"}, "parent") if (_has_db and _co_name) else none) %}
{% set _addr_raw = frappe.db.get_value("Address", _addr_name, ["address_line1", "address_line2", "city", "state", "country", "phone"], as_dict=True) if (_has_db and _addr_name is string and _addr_name | trim) else none %}
{% set addr = _addr_raw if (_addr_raw is mapping) else {} %}
{% set biz_name = (co.get("company_name") if (co.get("company_name") is string and co.get("company_name") | trim) else none) or _co_name or _rest_name %}
{% set _outlet_parts = [] %}
{% if _rest_name and _rest_name != biz_name %}{% set _noop = _outlet_parts.append(_rest_name) %}{% endif %}
{% if _branch_name and _branch_name != biz_name and _branch_name != _rest_name %}{% set _noop = _outlet_parts.append(_branch_name) %}{% endif %}
{% set outlet_line = _outlet_parts | join(" · ") %}
{% set _addr_parts = [] %}
{% for _ap in [addr.get("address_line1"), addr.get("address_line2"), addr.get("city")] %}{% if _ap is string and _ap | trim %}{% set _noop = _addr_parts.append(_ap | trim) %}{% endif %}{% endfor %}
{% set addr_line = _addr_parts | join(", ") %}
{% set biz_phone = (addr.get("phone") if (addr.get("phone") is string and addr.get("phone") | trim) else none) or (co.get("phone_no") if (co.get("phone_no") is string and co.get("phone_no") | trim) else none) %}
{% set seller_tin = (rest.get("tax_id") if (rest.get("tax_id") is string and rest.get("tax_id") | trim) else none) or (co.get("tax_id") if (co.get("tax_id") is string and co.get("tax_id") | trim) else none) %}
{% set _logo_raw = (rest.get("image") if (rest.get("image") is string and rest.get("image") | trim) else none) or (co.get("company_logo") if (co.get("company_logo") is string and co.get("company_logo") | trim) else none) %}
{% set logo_url = (resolve_bill_logo_src(_logo_raw) if (resolve_bill_logo_src is defined and _logo_raw) else _logo_raw) %}
{% set partner = doc.get("ury_print_partner") %}
{% set bills = [doc, partner] if partner else [doc] %}
{% set is_return_bill = doc.get("is_return") or (partner and partner.get("is_return")) %}
{% set _reprinted_raw = doc.get("copy_timestamp") or (frappe.utils.now() if (frappe is defined and frappe.utils is defined and frappe.utils.now is defined) else "") %}
{% set _reprinted = ((_reprinted_raw | string) | trim).split(".", 1)[0] if _reprinted_raw else "" %}
{% set _pd_raw = ((doc.get("posting_date") | string) | trim) if doc.get("posting_date") else "" %}
{% set _has_pd = _pd_raw and (not _pd_raw.startswith("<MagicMock")) and (_pd_raw != "None") %}
{% set _date_str = (frappe.utils.formatdate(doc.get("posting_date")) if (frappe is defined and frappe.utils is defined and frappe.utils.formatdate is defined and not _pd_raw.startswith("<")) else _pd_raw) if _has_pd else "" %}
{% set _pt_raw = ((doc.get("posting_time") | string) | trim) if doc.get("posting_time") else "" %}
{% set _has_pt = _pt_raw and (not _pt_raw.startswith("<MagicMock")) and (_pt_raw != "None") %}
{% set _pt_clean = _pt_raw.split(".", 1)[0] if _has_pt else "" %}
{% set _time_str = (frappe.utils.format_time(doc.get("posting_time"), "HH:mm") if (frappe is defined and frappe.utils is defined and frappe.utils.format_time is defined and not _pt_raw.startswith("<")) else _pt_clean[:5]) if _has_pt else "" %}
{% set _suppress_lh = (no_letterhead is defined and no_letterhead) %}
{% set _show_lh = (not _suppress_lh) and (letter_head is defined and letter_head is string and letter_head | trim) and ("letterhead-container" not in letter_head) and ("invoice-header" not in letter_head) %}
{% set _show_ft = (not _suppress_lh) and (footer is defined and footer is string and footer | trim) %}
<article class="sr">
{% if logo_url %}<div class="c"><img class="logo" src="{{ logo_url | e }}" alt=""></div>{% endif %}
{% if biz_name %}<div class="c hd" dir="auto">{{ biz_name | e }}</div>{% endif %}
{% if outlet_line %}<div class="c sub" dir="auto">{{ outlet_line | e }}</div>{% endif %}
{% if addr_line %}<div class="c sub" dir="auto">{{ addr_line | e }}</div>{% endif %}
{% if biz_phone %}<div class="c sub">{{ _("Tel") }} {{ biz_phone | e }}</div>{% endif %}
{% if seller_tin %}<div class="c sub">TIN: {{ seller_tin | e }}</div>{% endif %}
{% if _show_lh %}<div class="c lh sub" dir="auto">{{ letter_head }}</div>{% endif %}
<h1 class="c kind">{{ _("COPY") }} #{{ _copy_no | e }}</h1>
<hr>
<table>
{% if doc.get("name") %}<tr><td>{{ _("Original invoice") }}</td><td class="mv">{{ doc.get("name") | e }}</td></tr>{% endif %}
{% if _reprinted %}<tr><td>{{ _("Reprinted") }}</td><td class="mv">{{ _reprinted | e }}</td></tr>{% endif %}
{% if _date_str %}<tr><td>{{ _("Posting date") }}</td><td class="mv">{{ _date_str | e }}{% if _time_str %} {{ _time_str | e }}{% endif %}</td></tr>{% endif %}
{% if doc.get("customer_name") is string and doc.get("customer_name") | trim %}<tr><td>{{ _("Customer") }}</td><td class="mv" dir="auto">{{ doc.get("customer_name") | e }}</td></tr>{% endif %}
{% if doc.get("restaurant_table") is string and doc.get("restaurant_table") | trim %}<tr><td>{{ _("Table") }}</td><td class="mv">{{ _("Table") }} {{ doc.get("restaurant_table") | e }}</td></tr>{% endif %}
</table>
{% for bill in bills %}
{% if bill is not sameas doc %}<hr><div class="c b">{{ _("Merged invoice") }}: {{ bill.get("name") | e }}</div>{% endif %}
{% set _bill_curr = bill.get("currency") or "" %}
{% set _sc_rows = [] %}
{% set _tax_rows = [] %}
{% for _t in (bill.get("taxes") or []) %}
{% set _t_txt = ((_t.description if (_t.description is string) else "") ~ " " ~ (_t.get("account_head") if (_t.get("account_head") is string) else "")) | lower %}
{% if "service charge" in _t_txt %}{% set _noop = _sc_rows.append(_t) %}{% else %}{% set _noop = _tax_rows.append(_t) %}{% endif %}
{% endfor %}
<hr>
<table>
<tr><td class="q b">{{ _("Qty") }}</td><td class="b">{{ _("Item") }}</td><td class="a b">{{ _("Amount") }}{% if _bill_curr %} ({{ _bill_curr | e }}){% endif %}</td></tr>
{% for row in (bill.get("items") or []) %}
{% set _is_mod = (row.get("custom_is_modifier") is defined and row.get("custom_is_modifier")) %}
{% set _mod_prefix_raw = row.get("custom_modifier_prefix") %}
{% set _mod_prefix = (_mod_prefix_raw | trim) if (_mod_prefix_raw is string and _mod_prefix_raw | trim) else "" %}
{% set _note_str = (format_receipt_item_notes(row) if (format_receipt_item_notes is defined) else (row.get("comment") if (row.get("comment") is string) else "")) | trim %}
<tr{% if _is_mod %} class="mod-row"{% endif %}>
<td class="q">{% if not _is_mod %}{{ (row.qty | int) if (row.qty is number and row.qty == (row.qty | int)) else row.qty }}{% endif %}</td>
<td><div{% if _is_mod %} class="mod-name"{% endif %} dir="auto">{% if _is_mod %}+ {% if _mod_prefix %}{{ _mod_prefix | e }} {% endif %}{% endif %}{{ (row.item_name or '') | e }}</div>{% if _note_str %}<div class="mod" dir="auto">- {{ _note_str | e }}</div>{% endif %}{% if (not _is_mod) and row.qty is number and row.qty != 1 and row.get("rate") is number and row.get("rate") %}<div class="sub">@ {{ _money(row.get("rate"), _bill_curr) }}</div>{% endif %}</td>
<td class="a">{{ _money(row.amount, _bill_curr) }}</td>
</tr>
{% endfor %}
</table>
<hr>
<table>
{% set _sub_val = bill.get("total") if (bill.get("total") is number and bill.get("total")) else bill.get("net_total") %}
{% if _sub_val is number and _sub_val %}<tr><td>{{ _("Subtotal") }}</td><td class="a">{{ _money(_sub_val, _bill_curr) }}</td></tr>{% endif %}
{% if bill.get("discount_amount") is number and bill.get("discount_amount") %}<tr><td>{{ _("Discount") }}{% if bill.get("additional_discount_percentage") is number and bill.get("additional_discount_percentage") %} ({{ (bill.get("additional_discount_percentage") | int) if (bill.get("additional_discount_percentage") == (bill.get("additional_discount_percentage") | int)) else bill.get("additional_discount_percentage") }}%){% endif %}</td><td class="a">-{{ _money(bill.get("discount_amount"), _bill_curr) }}</td></tr>{% endif %}
{% for _is_tax, _rows in [(false, _sc_rows), (true, _tax_rows)] %}{% for _r in _rows %}{% if _r.tax_amount is number and _r.tax_amount %}{% set _r_rate = _r.get("rate") %}{% set _rate_s = ((_r_rate | int) if (_r_rate == (_r_rate | int)) else _r_rate) | string if (_r_rate is number and _r_rate) else "" %}{% set _desc_s = (_r.description | string) if (_r.description is defined and _r.description) else "" %}<tr><td{% if _is_tax %} class="sub"{% endif %}>{{ _r.description | striptags | e }}{% if _rate_s and (_rate_s ~ "%") not in _desc_s %} ({{ _rate_s }}%){% endif %}{% if _is_tax and _r.get("included_in_print_rate") %} {{ _("(incl.)") }}{% endif %}</td><td class="a{% if _is_tax %} sub{% endif %}">{{ _money(_r.tax_amount, _bill_curr) }}</td></tr>{% endif %}{% endfor %}{% endfor %}
{% if bill.get("rounding_adjustment") is number and bill.get("rounding_adjustment") %}<tr><td class="sub">{{ _("Rounding") }}</td><td class="a sub">{{ _money(bill.get("rounding_adjustment"), _bill_curr) }}</td></tr>{% endif %}
{% if bill.get("grand_total") is not none %}<tr><td class="t">{{ _("Grand total") }}</td><td class="a t">{{ _money(bill.get("grand_total"), _bill_curr) }}</td></tr>{% endif %}
{% if bill.get("rounded_total") is number and bill.get("rounded_total") and bill.get("rounded_total") != bill.get("grand_total") %}<tr><td>{{ _("Rounded total") }}</td><td class="a">{{ _money(bill.get("rounded_total"), _bill_curr) }}</td></tr>{% endif %}
</table>
{% set _paid_rows = [] %}{% for payment in (bill.get("payments") or []) %}{% if payment.amount %}{% set _noop = _paid_rows.append(payment) %}{% endif %}{% endfor %}
{% if _paid_rows or (bill.get("change_amount") is number and bill.get("change_amount")) %}
<hr>
{% for payment in _paid_rows %}<div class="sub">{{ payment.mode_of_payment | e }}: {{ _money(payment.amount, _bill_curr) }}</div>{% endfor %}
{% if bill.get("change_amount") is number and bill.get("change_amount") %}<div class="sub">{{ _("Change") }}: {{ _money(bill.get("change_amount"), _bill_curr) }}</div>{% endif %}
{% endif %}
{% if bill.get("outstanding_amount") is number and bill.get("outstanding_amount") > 0 %}
<div class="sub">{{ _("Outstanding") }}: {{ _money(bill.get("outstanding_amount"), _bill_curr) }}</div>
<div class="sub">{{ _("Charged to account") }} {{ (bill.get("customer") or '') | e }}: {{ _money(bill.get("outstanding_amount"), _bill_curr) }}</div>
{% endif %}
{% set bill_ef = efris_receipt_data(bill) if (efris_receipt_data is defined and bill.get("docstatus") == 1) else none %}
{% if bill_ef %}
<hr>
<div class="efris">
{% if partner and bill.get("name") is string and bill.get("name") | trim %}<div class="c sub b">{{ _("Check") }} {{ bill.get("name") | e }}</div>{% endif %}
{% if bill_ef.state == "fiscalised" %}
<div class="c b">URA EFRIS</div>
<table>
<tr><td>{{ _("FDN") }}</td><td class="mv b">{{ bill_ef.fdn | e }}</td></tr>
{% if bill_ef.verification_code %}<tr><td>{{ _("Verification code") }}</td><td class="mv b">{{ bill_ef.verification_code | e }}</td></tr>{% endif %}
{% if bill_ef.device_no %}<tr><td>{{ _("Device No") }}</td><td class="mv">{{ bill_ef.device_no | e }}</td></tr>{% endif %}
{% if bill_ef.issued %}<tr><td>{{ _("Issued") }}</td><td class="mv">{{ bill_ef.issued | e }}</td></tr>{% endif %}
{% if bill_ef.is_return and bill_ef.original_fdn %}<tr><td>{{ _("Original FDN") }}</td><td class="mv">{{ bill_ef.original_fdn | e }}</td></tr>{% endif %}
{% if bill.get("tax_id") is string and bill.get("tax_id") | trim %}<tr><td>{{ _("Buyer TIN") }}</td><td class="mv">{{ bill.get("tax_id") | e }}</td></tr>{% endif %}
</table>
{% set einv = frappe.get_doc("E Invoice", bill.get("efris_e_invoice")) if (bill.get("efris_e_invoice") is string and bill.get("efris_e_invoice") | trim and frappe is defined and frappe.get_doc is defined) else none %}
{% if einv and einv.taxes %}<table><tr><td class="sub b">{{ _("Tax category") }}</td><td class="a sub b" style="width:20mm">{{ _("Net") }}</td><td class="a sub b" style="width:20mm">{{ _("Tax") }}</td></tr>{% for t in einv.taxes %}<tr><td class="sub">{{ ((t.tax_category_code or "").split(":", 1) | last) | e }}</td><td class="a sub" style="width:20mm">{{ _money(t.net_amount, _bill_curr) }}</td><td class="a sub" style="width:20mm">{{ _money(t.tax_amount, _bill_curr) }}</td></tr>{% endfor %}</table>{% endif %}
{% if bill_ef.qr %}<div class="c" style="margin-top:1mm"><img src="{{ bill_ef.qr | e }}" alt="EFRIS QR" style="width:32mm;height:32mm"></div>{% endif %}
{% elif bill_ef.state == "credit_note_pending" or (bill.get("is_return") and bill_ef.state == "pending") %}
<div class="c b">{{ _("CREDIT NOTE PENDING URA APPROVAL") }}</div>
{% if bill_ef.application_ref %}<div class="c sub">{{ _("Application Ref") }}: {{ bill_ef.application_ref | e }}</div>{% endif %}
{% elif bill_ef.state == "pending" %}
<div class="c b">{{ _("FISCAL RECEIPT PENDING") }}</div>
<div class="c sub">{{ _("Not a tax invoice until URA issues the FDN. Ask for a reprint.") }}</div>
{% else %}
<div class="c sub">{{ _("Not a fiscal receipt") }}</div>
{% endif %}
{% if bill_ef.sandbox %}<div class="c sub b">*** {{ _("EFRIS SANDBOX - NOT A VALID TAX INVOICE") }} ***</div>{% endif %}
</div>
{% endif %}
{% endfor %}
{% if partner and ((not partner.get("currency")) or partner.get("currency") == doc.get("currency")) %}<hr><div class="b">{{ _("Combined grand total") }}: {{ _money((doc.get("grand_total") or 0) + (partner.get("grand_total") or 0), doc.get("currency")) }}</div>{% endif %}
{% set _has_pos_pay = namespace(found=false) %}{% for bill in bills %}{% for p in (bill.get("payments") or []) %}{% if p.amount is number and p.amount > 0 %}{% set _has_pos_pay.found = true %}{% endif %}{% endfor %}{% endfor %}
{% if not is_return_bill and _has_pos_pay.found %}
{% set _has_clearing_field = _has_db and frappe.get_meta is defined and frappe.get_meta("Company").has_field("custom_guest_ledger_clearing") %}
{% set _clearing_raw = frappe.db.get_value("Company", _co_name, "custom_guest_ledger_clearing") if (_has_clearing_field and _co_name) else none %}
{% set clearing = (_clearing_raw | trim) if (_clearing_raw is string and _clearing_raw | trim) else none %}
{% set rc = namespace(charged=0, room="", folio="", guest="") %}
{% for bill in bills %}{% for p in (bill.get("payments") or []) %}{% if p.amount is number and p.amount > 0 and ((clearing and p.get("account") is string and p.get("account") == clearing) or (not clearing and p.get("mode_of_payment") is string and (p.get("mode_of_payment") | trim | lower) == "room charge")) %}{% set rc.charged = rc.charged + p.amount %}{% endif %}{% endfor %}{% if not rc.room and bill.get("room_number") is string and bill.get("room_number") | trim %}{% set rc.room = bill.get("room_number") | trim %}{% endif %}{% if not rc.folio and bill.get("kamra_ref") is string and bill.get("kamra_ref") | trim %}{% set rc.folio = bill.get("kamra_ref") | trim %}{% endif %}{% if not rc.guest and bill.get("custom_guest_label") is string and bill.get("custom_guest_label") | trim %}{% set rc.guest = bill.get("custom_guest_label") | trim %}{% elif not rc.guest and bill.get("customer_name") is string and (bill.get("customer_name") | trim) and (bill.get("customer_name") | trim | lower) != "walk in" %}{% set rc.guest = bill.get("customer_name") | trim %}{% endif %}{% endfor %}
{% if rc.charged > 0 %}
{% set stay = frappe.db.get_value("Folio", rc.folio, ["guest_name", "reservation"], as_dict=True) if (rc.folio and _has_db) else none %}
{% if not rc.room and stay and stay.reservation and _has_db %}{% set stay_room = frappe.db.get_value("Reservation", stay.reservation, "room") %}{% set rc.room = ((frappe.db.get_value("Room", stay_room, "room_number") or stay_room) | trim) if stay_room else "" %}{% endif %}
{% set rc_guest = (stay.guest_name | trim) if (stay and stay.guest_name is string and stay.guest_name | trim) else rc.guest %}
{% if not rc.room and rc_guest %}{% set _rm_cand = (rc_guest.split("—", 1)[0].split("–", 1)[0].split(" - ", 1)[0].split(",", 1)[0]) | trim %}{% set _rm_low = _rm_cand | lower %}{% if _rm_low.startswith("room ") or _rm_low.startswith("suite ") or _rm_low.startswith("rm ") or _rm_low.startswith("rm.") or _rm_low.startswith("villa ") or _rm_low.startswith("apt ") %}{% set rc.room = _rm_cand %}{% endif %}{% endif %}
<hr>
<div class="c kind">{{ _("ROOM CHARGE") }}</div>
<table>
<tr><td class="rc-l">{{ _("Room") }} :</td><td class="rc-v b">{{ (rc.room | e) if rc.room else "__________" }}</td></tr>
{% if rc_guest %}<tr><td class="rc-l">{{ _("Guest") }} :</td><td class="rc-v b" dir="auto">{{ rc_guest | e }}</td></tr>{% endif %}
<tr><td class="rc-l">{{ _("Charged to room") }} :</td><td class="rc-v b">{{ _money(rc.charged, doc.get("currency")) }}</td></tr>
</table>
<div class="sig c sub">{{ _("Guest signature") }}</div>
<div class="sig c sub">{{ _("Name (print)") }}</div>
{% endif %}
{% endif %}
<hr>
{% if _show_ft %}<div class="c ft sub" dir="auto">{{ footer }}</div>{% else %}<div class="c sub">{{ _("Thank you") }}</div>{% endif %}
</article>
